changeSet.sql:
UPDATE REFDATA.TM_INTERVAL SET DISPLAY_NAME = 'Daily', UPDATED_AT = NOW()
 WHERE TM_INTERVAL_ID = 1 AND DISPLAY_NAME IS NULL;

UPDATE REFDATA.TM_INTERVAL SET DISPLAY_NAME = 'Hourly', UPDATED_AT = NOW()
 WHERE TM_INTERVAL_ID = 2 AND DISPLAY_NAME IS NULL;

UPDATE REFDATA.TM_INTERVAL SET DISPLAY_NAME = NAME, UPDATED_AT = NOW()
 WHERE DISPLAY_NAME IS NULL;

ALTER TABLE REFDATA.TM_INTERVAL
    ALTER COLUMN DISPLAY_NAME SET NOT NULL;
